
-- Farmer list cards: show the farmer's administrative hierarchy plus the two
-- requested personal fields. This metadata override remains in the extension;
-- no staff-portal base source changes are required.
UPDATE "public"."g2p_register_schemas"
SET "search_result_schema" = '[{"field_name": "region_name", "display_label": "Region", "order": 1}, {"field_name": "zone_name", "display_label": "Zone", "order": 2}, {"field_name": "woreda_name", "display_label": "Woreda", "order": 3}, {"field_name": "kebele_name", "display_label": "Kebele", "order": 4}, {"field_name": "state", "display_label": "State", "order": 5}, {"field_name": "import_source", "display_label": "Import Source", "order": 6}]'
WHERE "register_id" = 'a1a4d25a-1cd4-4356-abac-985a0b3c6bcd';

-- Add State/Import Source dropdown filters alongside the existing Gender/Birthdate/Record Status ones.
UPDATE "public"."g2p_register_schemas"
SET "filter_schema" = '[{"field_name": "first_name", "display_label": "First Name", "filter_type": "text", "order": 1, "allowed_operators": ["eq", "contains"]}, {"field_name": "last_name", "display_label": "Last Name", "filter_type": "text", "order": 2, "allowed_operators": ["eq", "contains"]}, {"field_name": "gender", "display_label": "Gender", "filter_type": "dropdown", "order": 3, "allowed_operators": ["eq", "in"], "options_source": [{"value": "MALE", "label": "MALE"}, {"value": "FEMALE", "label": "FEMALE"}, {"value": "OTHERS", "label": "OTHERS"}, {"value": "UNKNOWN", "label": "UNKNOWN"}]}, {"field_name": "birth_date", "display_label": "Birthdate", "filter_type": "date_range", "order": 4, "allowed_operators": ["eq", "gt", "gte", "lt", "lte", "between"]}, {"field_name": "record_status", "display_label": "Record Status", "filter_type": "dropdown", "order": 5, "allowed_operators": ["eq", "in"], "options_source": [{"value": "ACTIVE", "label": "ACTIVE"}, {"value": "INACTIVE", "label": "INACTIVE"}, {"value": "ARCHIVED", "label": "ARCHIVED"}]}, {"field_name": "state", "display_label": "State", "filter_type": "dropdown", "order": 6, "allowed_operators": ["eq", "in"], "options_source": [{"value": "DRAFT", "label": "DRAFT"}, {"value": "PENDING", "label": "PENDING"}, {"value": "APPROVED", "label": "APPROVED"}, {"value": "REJECTED", "label": "REJECTED"}, {"value": "CANCELLED", "label": "CANCELLED"}]}, {"field_name": "import_source", "display_label": "Import Source", "filter_type": "dropdown", "order": 7, "allowed_operators": ["eq", "in"], "options_source": [{"value": "INTAKE_FORM", "label": "INTAKE_FORM"}, {"value": "IMPORT_FILE", "label": "IMPORT_FILE"}, {"value": "PARTNER", "label": "PARTNER"}, {"value": "STAFF_PORTAL", "label": "STAFF_PORTAL"}, {"value": "BENEFICIARY_PORTAL", "label": "BENEFICIARY_PORTAL"}, {"value": "AGENT_PORTAL", "label": "AGENT_PORTAL"}, {"value": "VERIFIABLE_CREDENTIAL", "label": "VERIFIABLE_CREDENTIAL"}]}]'
WHERE "register_id" = 'a1a4d25a-1cd4-4356-abac-985a0b3c6bcd';
